// ClockClock 24 engine, ported from components/lvgl_clock/lvgl_clock.cpp.
//
// This is a DELIBERATE line-for-line port, not a reimplementation: the same
// constants, the same tables, the same per-frame maths, so a choreography
// prototyped here drops into the C++ with only syntax changes. Where the C++
// writes `this->cur_[i]`, this writes `cur[i]`; where it uses `wall_pos_(c)`,
// this uses `wallPos(c)`. Keep it that way.
//
// Loaded as a CLASSIC script (no ES modules), so index.html opens straight
// from file:// with no server. Everything lands on window.CC at the bottom.
//
// Angles are degrees, 0 = 12 o'clock, clockwise. cur[] is 48 hands:
// hand index = clock * 2 + hand, clock = digit * 6 + cell, cell = row * 2 + col.

const NUM_DIGITS = 4;
const CLOCKS_PER_DIGIT = 6;
const NUM_CLOCKS = NUM_DIGITS * CLOCKS_PER_DIGIT;   // 24
const NUM_HANDS = NUM_CLOCKS * 2;                   // 48
const WALL_COLS = 8;
const WALL_ROWS = 3;

const PARK = 225.0;   // clockclock idle: both hands to bottom-left

// ---------------------------------------------------------------- glyphs ----
// Target angle of the two hands of each of a digit's 6 clocks (TL,TR,ML,MR,BL,BR).
const FONT = [
  [[90,180],[180,270],[0,180],[0,180],[0,90],[0,270]],            // 0
  [[PARK,PARK],[180,180],[PARK,PARK],[0,180],[PARK,PARK],[0,0]],  // 1
  [[90,90],[180,270],[90,180],[0,270],[0,90],[270,270]],          // 2
  [[90,90],[180,270],[90,90],[0,270],[90,90],[0,270]],            // 3
  [[180,180],[180,180],[0,90],[0,180],[PARK,PARK],[0,0]],         // 4
  [[90,180],[270,270],[0,90],[180,270],[90,90],[0,270]],          // 5
  [[90,180],[270,270],[0,180],[180,270],[0,90],[0,270]],          // 6
  [[90,90],[180,270],[PARK,PARK],[0,180],[PARK,PARK],[0,0]],      // 7
  [[90,180],[180,270],[0,90],[0,270],[0,90],[0,270]],             // 8
  [[90,180],[180,270],[0,90],[0,180],[90,90],[0,270]],            // 9
];

const LOVE = [
  [[180,180],[PARK,PARK],[0,180],[PARK,PARK],[0,90],[270,270]],   // L
  [[90,180],[180,270],[0,180],[0,180],[0,90],[0,270]],            // O
  [[180,180],[180,180],[0,180],[0,180],[0,105],[0,255]],          // V
  [[90,180],[270,270],[0,180],[270,270],[0,90],[270,270]],        // E
];

const TG_DEGREE = 0, TG_C = 1, TG_MINUS = 2, TG_BLANK = 3;
const TEMP_GLYPHS = [
  [[90,180],[180,270],[0,90],[0,270],[PARK,PARK],[PARK,PARK]],                 // degree
  [[PARK,PARK],[PARK,PARK],[90,180],[270,270],[0,90],[270,270]],               // c
  [[PARK,PARK],[PARK,PARK],[90,90],[270,270],[PARK,PARK],[PARK,PARK]],         // minus
  [[PARK,PARK],[PARK,PARK],[PARK,PARK],[PARK,PARK],[PARK,PARK],[PARK,PARK]],   // blank
];

// --------------------------------------------------------------- helpers ----
const wrap360 = a => ((a % 360) + 360) % 360;

function shortestDelta(a, b) {
  let d = (b - a) % 360;
  if (d < 0) d += 360;
  if (d > 180) d -= 360;
  return d;
}

// smootherstep: starts and ends at rest. For moves that begin from a hold.
const ease = t => t * t * t * (t * (t * 6 - 15) + 10);
// Decelerate-only: full speed at t=0. For LEAVING a choreography, which is
// already moving — smootherstep there reads as a pause before the clock returns.
const easeOut = t => { const u = 1 - t; return 1 - u * u * u; };

function wallPos(c) {
  const digit = Math.floor(c / CLOCKS_PER_DIGIT);
  const cell = c % CLOCKS_PER_DIGIT;
  return { row: Math.floor(cell / 2), col: digit * 2 + (cell % 2) };
}

// ------------------------------------------------------------- constants ----
const K = {
  COLUMN_STAGGER_MS: 250,
  CYCLE_WINDOW_S: 35,
  CYCLE_OFFSET_S: 10,
  TEMP_UPDATE_BUFFER_S: 1.0,

  BIRDS_RATE_RAD_S: 2.0 * 0.5,
  BIRDS_COL_LAG_S: 0.15,
  BIRDS_RAMP_S: 2.5,

  WAVE_TURN_S: 15.3,
  WAVE_COL_LAG_DEG: 15.0,
  WAVE_REST_DEG: 315.0,
  WAVE_RAMP_S: 1.0,

  SPIRAL_TURN_S: 7.5,
  SPIRAL_DIAG_LAG_DEG: 40.0,
  SPIRAL_RAMP_S: 1.0,

  WIND_BEND_DEG: 90.0,
  WIND_RISE_S: 2.0,
  WIND_HOLD_S: 0.0,
  WIND_FALL_S: 2.0,
  WIND_SPREAD_S: 1.2,
  get WIND_CYCLE_S() {
    return this.WIND_RISE_S + 2 * this.WIND_SPREAD_S + this.WIND_HOLD_S + this.WIND_FALL_S;
  },
};

// ---------------------------------------------------------- choreographies --
// Each takes (cur, t, ctx) and writes 48 angles into cur. t is seconds of
// animation time; ctx carries { modeSpeed, digits, temp }.
//
// ADD A NEW MODE HERE. Register it in MODES at the bottom, and it appears in
// the UI automatically.

function tickRotate(cur, t, { modeSpeed }) {
  const ang = (t * 45.0 * modeSpeed) % 360;
  const a = 360 - ang;
  for (let c = 0; c < NUM_CLOCKS; c++) {
    cur[c * 2 + 0] = a;
    cur[c * 2 + 1] = wrap360(a + 180);
  }
}

function tickBirds(cur, t, { modeSpeed }) {
  const rate = K.BIRDS_RATE_RAD_S * modeSpeed;
  const ts = t * modeSpeed;
  for (let c = 0; c < NUM_CLOCKS; c++) {
    const { col } = wallPos(c);
    const x = ts - col * K.BIRDS_COL_LAG_S;
    let ph;
    if (x <= 0) ph = 0;
    else if (x < K.BIRDS_RAMP_S) ph = rate * x * x / (2 * K.BIRDS_RAMP_S);
    else ph = rate * (x - K.BIRDS_RAMP_S / 2);
    const wing = 85 + 45 * Math.sin(ph % (2 * Math.PI));
    cur[c * 2 + 0] = wing;
    cur[c * 2 + 1] = 360 - wing;
  }
}

function tickWave(cur, t, { modeSpeed }) {
  const rate = 360 / K.WAVE_TURN_S;
  const colDelay = K.WAVE_COL_LAG_DEG / rate;
  const ts = t * modeSpeed;
  for (let c = 0; c < NUM_CLOCKS; c++) {
    const { col } = wallPos(c);
    const x = ts - col * colDelay;
    let turned;
    if (x <= 0) turned = 0;
    else if (x < K.WAVE_RAMP_S) turned = rate * x * x / (2 * K.WAVE_RAMP_S);
    else turned = rate * (x - K.WAVE_RAMP_S / 2);
    const a = wrap360(K.WAVE_REST_DEG + (turned % 360));
    cur[c * 2 + 0] = a;
    cur[c * 2 + 1] = wrap360(a + 180);
  }
}

function tickSpiral(cur, t, { modeSpeed }) {
  const span = (WALL_COLS - 1) + (WALL_ROWS - 1);
  const rate = 360 / K.SPIRAL_TURN_S;
  const ts = t * modeSpeed;
  for (let c = 0; c < NUM_CLOCKS; c++) {
    const { col, row } = wallPos(c);
    const diag = col + ((WALL_ROWS - 1) - row);
    const x = ts - (diag / span) * (K.SPIRAL_DIAG_LAG_DEG / rate);
    let turned;
    if (x <= 0) turned = 0;
    else if (x < K.SPIRAL_RAMP_S) turned = rate * x * x / (2 * K.SPIRAL_RAMP_S);
    else turned = rate * (x - K.SPIRAL_RAMP_S / 2);
    const a = wrap360(PARK - (turned % 360));
    cur[c * 2 + 0] = a;
    cur[c * 2 + 1] = a;
  }
}

// A gust bending a stalk. Read a column top to bottom and the three clocks are
// one continuous stroke; only the two free ends move, and they shear past each
// other — top tip 10:30→1:30 over the top, bottom tip 4:30→7:30 underneath.
function tickWind(cur, t, { modeSpeed }) {
  const REST = [[315, 180], [0, 180], [0, 135]];
  const MOVES = [0, -1, 1];      // which hand the gust bends, -1 = none
  const SENSE = [1, 0, 1];
  const ts = t * modeSpeed;

  for (let c = 0; c < NUM_CLOCKS; c++) {
    const { col, row } = wallPos(c);
    let u = ts % K.WIND_CYCLE_S;
    if (u < 0) u += K.WIND_CYCLE_S;

    // The bottom row reads the wall from the other end in BOTH phases:
    //   top     push  left→right    release  right→left
    //   bottom  push  right→left    release  left→right
    const lag = col / (WALL_COLS - 1) * K.WIND_SPREAD_S;
    const eff = (row === WALL_ROWS - 1) ? (K.WIND_SPREAD_S - lag) : lag;
    const pushAt = eff;
    const releaseAt = K.WIND_RISE_S + K.WIND_HOLD_S + 2 * K.WIND_SPREAD_S - eff;

    let lean;
    if (u < pushAt) lean = 0;
    else if (u < pushAt + K.WIND_RISE_S) lean = K.WIND_BEND_DEG * ease((u - pushAt) / K.WIND_RISE_S);
    else if (u < releaseAt) lean = K.WIND_BEND_DEG;
    else if (u < releaseAt + K.WIND_FALL_S) lean = K.WIND_BEND_DEG * (1 - ease((u - releaseAt) / K.WIND_FALL_S));
    else lean = 0;
    lean *= SENSE[row];

    for (let hnd = 0; hnd < 2; hnd++) {
      let a = REST[row][hnd];
      if (MOVES[row] === hnd) a += lean;
      cur[c * 2 + hnd] = wrap360(a);
    }
  }
}

// A held pose, not an animation: the entry blend and the settle do the moving.
function poseFromTable(cur, table) {
  for (let d = 0; d < NUM_DIGITS; d++)
    for (let c = 0; c < CLOCKS_PER_DIGIT; c++)
      for (let h = 0; h < 2; h++)
        cur[(d * CLOCKS_PER_DIGIT + c) * 2 + h] = table[d][c][h];
}

function tickLove(cur) { poseFromTable(cur, LOVE); }

function tickTemp(cur, t, { temp }) {
  let v = temp, neg = false;
  if (v < 0) { neg = true; v = -v; }
  if (v > 99) v = 99;
  // [tens or sign] [units] [degree] [C]
  const glyph = [0, 0, TG_DEGREE, TG_C];
  const isDigit = [true, true, false, false];
  if (neg) { glyph[0] = TG_MINUS; isDigit[0] = false; glyph[1] = v > 9 ? 9 : v; }
  else if (v >= 10) { glyph[0] = Math.floor(v / 10); glyph[1] = v % 10; }
  else { glyph[0] = TG_BLANK; isDigit[0] = false; glyph[1] = v; }

  for (let d = 0; d < NUM_DIGITS; d++) {
    const src = isDigit[d] ? FONT[glyph[d]] : TEMP_GLYPHS[glyph[d]];
    for (let c = 0; c < CLOCKS_PER_DIGIT; c++)
      for (let h = 0; h < 2; h++)
        cur[(d * CLOCKS_PER_DIGIT + c) * 2 + h] = src[c][h];
  }
}

// ------------------------------------------------------ rotating_maze -------
// A chevron per clock, alternating by COLUMN - even columns point down (a
// peak), odd columns point up (a trough) - turning at one rate, with the
// DIRECTION alternating by ROW:
//
//   rows 0, 2   clockwise
//   row 1      counter-clockwise
//
// Both hands of a clock always turn the SAME way, so the pair stays a rigid
// 90 deg chevron and simply rotates - never opening or shutting in place.
//
// At t = 0 the wall is a clean interlocking pattern; the counter-rotating rows
// then shear past each other and it opens and closes through it, which is
// where the name comes from. The rate is not constant - see MAZE_FLOOR.
// One revolution AVERAGE, at mode_speed 1.0. With MAZE_STOPS = 4 that is a
// dwell every 5 s, and a whole revolution inside a 35 s cycle_modes window with
// room to spare.
const MAZE_TURN_S = 20.0;
// The turn does not run at a constant rate: it eases off where the pattern
// lands on an aligned figure, then runs on through the untidy angles between.
//
// Done as a TIME WARP, not a velocity: integrating a speed that depends on
// angle is an ODE, but bending the phase is closed-form and exact.
//
//   rate(x) = (1 - d G(x)) / (1 - d mean(G))        d set from MAZE_FLOOR
//   G(x)    = ((1 + cos x) / 2) ^ MAZE_SHARP          x = N (u - phi)
//
// The profile is a narrow BUMP, not a cosine. A plain cosine (MAZE_SHARP = 1)
// sits near its minimum for most of the cycle - 28% of every segment below half
// speed - which is why it read as stopping on each figure rather than easing
// past it. Raising the exponent narrows the dip WITHOUT deepening it: full
// speed through most of a segment, a brief ease as the figure lines up.
//
// G has a closed-form integral at any integer exponent, which is what keeps
// this exact rather than a lookup table:
//
//   G(x)  = cos^2k(x/2) = 4^-k [ C(2k,k) + 2 SUM_j C(2k,k-j) cos(jx) ]
//   IG(x) = 4^-k [ C(2k,k) x + 2 SUM_j C(2k,k-j) sin(jx)/j ]
//
// so theta(u) = (u - (d/N) IG(N(u - phi))) / (1 - d mean(G)), and
// theta(u + 2pi) = theta(u) + 2pi exactly - one whole turn per turn, however the
// rate is shaped.
// FOUR - one dwell every 90 deg, phased onto 45. The hands land on a 45 deg
// multiple every 45 deg of turn, which gives eight aligned figures per
// revolution in two families:
//
//   theta = 0, 90, 180, 270    chevrons - < > pairs, a diagonal lattice
//   theta = 45, 135, 225, 315  right-angle corners, a rectangular grid
//
// Only the FIRST family gets a dwell - the one where every hand sits on a
// DIAGONAL, which is the base pose the mode starts from. MAZE_PHASE_DEG = 0
// selects it; 45 picks the axis-aligned grid instead. Dwelling on both (STOPS
// 8) put a pause every 45 deg and made neither stand out.
//
// The rhythm per figure is MAZE_TURN_S / MAZE_STOPS.
const MAZE_STOPS = 4;          // slow-downs per revolution
// How NARROW the ease-off is - the exponent in the closed-form integral above,
// so a positive integer. 1 is a plain cosine and slows over most of the
// segment; higher concentrates the slowing into a short patch centred on the
// figure and leaves the rest of the segment at full speed.
const MAZE_SHARP = 8;
// The SLOWEST rate, as a fraction of the average - the one knob worth having
// here, because it is the thing you judge by eye. Any value in (0, 1] is safe
// by construction: the dip depth derived from it in MAZE_G always comes out
// <= 1, so the rate can never go negative and the hands can never run
// backwards. Lower = more of a pause on each figure, 1.0 = a constant rate.
const MAZE_FLOOR = 0.40;
const MAZE_PHASE_DEG = 0;      // which angle the slow-downs land on

// Binomial row C(2k, .), the mean of G, and the dip depth that lands the
// slowest rate exactly on MAZE_FLOOR. Worked out once at load:
//
//   floor = (1 - d) / (1 - d mean)   =>   d = (1 - floor) / (1 - floor mean)
//
const MAZE_G = (() => {
  const k = MAZE_SHARP, C = [1];
  for (let i = 1; i <= 2 * k; i++) {           // one row of Pascal's triangle
    C[i] = 1;
    for (let j = i - 1; j > 0; j--) C[j] = C[j] + C[j - 1];
  }
  const scale = Math.pow(4, -k);
  const mean = C[k] * scale;
  return { k, scale, coef: C, mean,
           dwell: (1 - MAZE_FLOOR) / (1 - MAZE_FLOOR * mean) };
})();

// The warped angle for a linear phase u, in radians. Monotonic in u, and
// mazeRaw(u + 2pi) = mazeRaw(u) + 2pi.
function mazeRaw(u) {
  const { k, scale, coef, mean, dwell } = MAZE_G;
  // MAZE_PHASE_DEG is the OUTPUT angle a dwell should land on, but the offset
  // has to be applied to the LINEAR phase - and the normalisation below divides
  // that by (1 - dwell*mean). So scale it first, or the dwells come out at
  // phase/(1 - dwell*mean): asking for 45 deg silently gave 51.6. Invisible
  // while the constant was 0, since 0 scales to 0.
  //
  //   minima land at  theta = MAZE_PHASE_DEG + k * 360/MAZE_STOPS
  //
  const phi = MAZE_PHASE_DEG * Math.PI / 180 * (1 - dwell * mean);
  const x = MAZE_STOPS * (u - phi);
  let ig = coef[k] * x;                        // the integral of G, term by term
  for (let j = 1; j <= k; j++) ig += 2 * coef[k - j] * Math.sin(j * x) / j;
  ig *= scale;
  return (u - (dwell / MAZE_STOPS) * ig) / (1 - dwell * mean);
}

// The linear phase at which the turn is back at zero.
//
// A non-zero MAZE_PHASE_DEG shifts the whole curve, so mazeRaw(0) is no longer
// 0 and the mode would START part-way round - the wall coming up on some
// arbitrary angle instead of its base pose. Solving for the u where the turn is
// zero and beginning there fixes the start WITHOUT moving the dwells, which
// subtracting mazeRaw(0) would have done. Bisection is fine: mazeRaw is
// monotonic by construction.
const MAZE_U0 = (() => {
  let lo = -Math.PI, hi = Math.PI;
  for (let i = 0; i < 100; i++) {
    const m = (lo + hi) / 2;
    if (mazeRaw(m) < 0) lo = m; else hi = m;
  }
  return (lo + hi) / 2;
})();

// Linear phase in, eased-around-the-figures angle out. Degrees.
function mazePhase(ts) {
  const TAU = Math.PI * 2;
  // Wrap the LINEAR phase, not the output: mazeRaw(u + TAU) = mazeRaw(u) + TAU,
  // so the seam is a whole turn and the hand does not step.
  let u = (ts / MAZE_TURN_S) * TAU % TAU;
  if (u < 0) u += TAU;
  return mazeRaw(u + MAZE_U0) * 180 / Math.PI;
}

function cellAt(cur, row, col, a, b) {
  const c = (col >> 1) * CLOCKS_PER_DIGIT + row * 2 + (col & 1);
  cur[c * 2 + 0] = a;
  cur[c * 2 + 1] = b;
}

function tickRotatingMaze(cur, t, { modeSpeed }) {
  const turned = mazePhase(t * modeSpeed);

  for (let row = 0; row < WALL_ROWS; row++) {
    // Whole ROWS turn opposite ways: rows 0 and 2 clockwise, row 1
    // counter-clockwise. Both hands of a clock always take the SAME direction,
    // so the pair stays a rigid 90 deg chevron and simply turns.
    const sense = (row & 1) ? -1 : 1;
    for (let col = 0; col < WALL_COLS; col++) {
      // even column: 135/225, a chevron pointing DOWN
      // odd  column:  45/315, a chevron pointing UP
      const base = (col & 1) ? [45, 315] : [135, 225];
      cellAt(cur, row, col,
             wrap360(base[0] + sense * turned),
             wrap360(base[1] + sense * turned));
    }
  }
}

// ------------------------------------------------------------- zipper ------
// The whole wall rests as one field of top-left-to-bottom-right diagonals, and
// a front travels across it from left to right, unzipping each column into a
// pair of mirrored chevrons and doing it back up behind.
//
//   at rest   \  \  \  \  \  \  \  \
//   the front \  \  \  >  <  /  /  /      the two hands have come apart
//   after     /  /  /  /  /  /  /  /      ...and closed again on the far side
//
// The rest pose puts the hands 180 deg apart (315 and 135), so a column at rest
// is ONE straight stroke. A pass swings each hand by 90 deg, which turns the
// stroke from \\ to / - and the next pass turns it back.
//
// TWO THINGS MAKE THE FIGURE, and it does not appear without either:
//
//   1. The swing is 90 deg, not 180. At 180 the chevron's opening rotates all
//      the way round - > then v then < then ^ - so no single shape is ever on
//      screen for more than an instant.
//   2. Hand 1 does not start until hand 0 has FINISHED (ZIP_HAND_LAG_S >
//      ZIP_FLIP_S). Overlap the two and they are never more than about 40 deg
//      apart, which is a slightly bent line rather than a chevron. Separated,
//      the stroke opens to a full right angle and HOLDS there for
//      HAND_LAG - FLIP seconds before closing.
//
// Which hand leads alternates by column, so the front is a row of mirrored
// chevrons - > < > < - rather than eight identical ones.
// One hand's 90 deg swing. The eased swing peaks at 1.875x its average rate and
// mode_speed scales it, so going much below this breaks the 20 deg/frame
// ceiling in check.js at mode_speed 3.
const ZIP_FLIP_S = 0.9;
// Hand 1 behind hand 0. MUST EXCEED ZIP_FLIP_S - the difference is how long
// the chevron is held fully open before it shuts.
const ZIP_HAND_LAG_S = 1.2;
// A column is in motion for HAND_LAG + FLIP = 2.1 s, so the number of columns
// moving AT ONCE is that divided by the lag between them. Too small and every
// column moves at once and there is no front to see; 0.5 s keeps it to about
// FOUR, with the rest of the wall sitting still on the diagonal.
const ZIP_COL_LAG_S = 0.5;
// Set from the GAP wanted between one front and the next, in columns. A column
// is in motion for HAND_LAG + FLIP = 2.1 s, which at COL_LAG is a front about
// four columns wide; resting a further ZIP_GAP_COLS worth on top of that sets
// how closely the fronts follow each other.
//
//   spatial period = (front width + gap) columns
//   cycle          = motion + gap * COL_LAG = FLIP + HOLD
//
// At 9 the gap is wide enough that a front finishes crossing before the next
// sets off, so there is only ever ONE front on the wall - it arrives, passes
// through, and the wall is a clean field of diagonals again before the next
// one starts. A small gap (2) keeps a front on the wall permanently with the
// next already coming in behind it, which reads as much busier.
const ZIP_GAP_COLS = 9;
// How far a resting column drifts before the next pass reaches it. Applied to
// BOTH hands, so a resting stroke stays straight and simply leans - the wall is
// never quite frozen between passes.
//
// It ramps across the whole rest, so this also SETS THE SPEED: the lean rate is
// ZIP_DRIFT_DEG / ZIP_HOLD_S. At 30 deg over a 5.7 s rest that is ~5.3 deg/s,
// which is clearly moving without the field ever straying far from its
// diagonal.
//
// The direction comes from which pose the column is currently resting on, and
// since a pass flips it between \\ and /, the drift reverses every pass. That is
// what keeps it BOUNDED: it sways between 0 and this and back, instead of a
// constant creep that would have the field far off \\ within a minute.
const ZIP_DRIFT_DEG = 30;
const ZIP_HOLD_S = ZIP_HAND_LAG_S + ZIP_GAP_COLS * ZIP_COL_LAG_S;
const ZIP_CYCLE_S = ZIP_FLIP_S + ZIP_HOLD_S;

// How far through its 90 deg swing one hand is at time x, 0..1.
//
// It SWINGS OUT AND BACK rather than accumulating: pass 0 goes 0 -> 1, pass 1
// goes 1 -> 0, and so on. Accumulating instead - each pass carrying on round -
// leaves every pass starting from a base 90 deg further along, so the second
// pass opens its chevrons downwards (v and ^) instead of sideways. Swinging
// keeps the figure in the same > < family every time.
//
// Continuous at the seam: an even pass ends at 1 and the next odd pass starts
// at 1 - 0 = 1, so the hand holds rather than steps.
function zipSwing(x) {
  // Nothing has happened yet. Without this the columns to the right - whose
  // lag puts them at negative x - would already be part-way through a swing at
  // t = 0, and the wall would not start as one clean field of diagonals for
  // the mode-entry blend to fade into.
  if (x <= 0) return 0;
  const n = Math.floor(x / ZIP_CYCLE_S);
  const u = x - n * ZIP_CYCLE_S;
  const p = u < ZIP_FLIP_S ? ease(u / ZIP_FLIP_S) : 1;
  return (n & 1) ? 1 - p : p;
}

// The slow lean of a resting column, in degrees.
//
// Holds still while the column is mid-swing, then ramps across the rest that
// follows - to ZIP_DRIFT_DEG after an even pass (resting on /), back to 0
// after an odd one (resting on \\). Continuous at every seam, and it never
// leaves [0, ZIP_DRIFT_DEG].
function zipDrift(x) {
  if (x <= 0) return 0;
  const n = Math.floor(x / ZIP_CYCLE_S);
  const u = x - n * ZIP_CYCLE_S;
  const from = (n & 1) ? ZIP_DRIFT_DEG : 0;       // where this cycle starts
  const to = (n & 1) ? 0 : ZIP_DRIFT_DEG;         // and where its rest takes it
  if (u < ZIP_FLIP_S) return from;                // mid-swing: hold
  return from + (to - from) * ((u - ZIP_FLIP_S) / ZIP_HOLD_S);
}

function tickZipper(cur, t, { modeSpeed }) {
  const ts = t * modeSpeed;
  for (let col = 0; col < WALL_COLS; col++) {
    const x = ts - col * ZIP_COL_LAG_S;           // the front, travelling right
    // WHICH hand leads is what makes the figure: whichever goes first drags the
    // stroke open towards its own side. Alternating it by column gives the
    // front a row of mirrored chevrons - > < > < - rather than eight identical
    // ones.
    const lead = (col & 1) === 0;
    const x0 = lead ? x : x - ZIP_HAND_LAG_S;
    const x1 = lead ? x - ZIP_HAND_LAG_S : x;
    // The drift is read at the column's own x and added to BOTH hands, so a
    // resting stroke leans without bending.
    const drift = zipDrift(x);
    const a0 = wrap360(315 + 90 * zipSwing(x0) + drift);
    const a1 = wrap360(135 + 90 * zipSwing(x1) + drift);
    // Every row does the same thing, so the figure repeats down each column and
    // the front is one vertical band crossing the wall.
    //
    // Two variations were tried and are wrong: giving the middle row the
    // opposite travel direction puts the rows at different columns, so the wall
    // stops reading as a single front; giving it the opposite swing sign turns
    // its chevrons through a right angle, which breaks the column into three
    // unrelated marks.
    for (let row = 0; row < WALL_ROWS; row++)
      cellAt(cur, row, col, a0, a1);
  }
}

// -------------------------------------------------------- mirror_wave ------
// Every clock rests as one vertical stroke - both hands on the 12-6 line - and
// then scissors open, the two hands parting like a pair of dividers.
//
// The wall is MIRRORED about its centre line: the left half opens to the right
// and the right half opens to the left, so the chevrons always point inwards at
// the middle and the two halves are reflections of each other at every instant.
//
// The middle row opens the OTHER WAY from the two around it, so a column is
// three alternating chevrons rather than three identical ones.
//
// It starts in the MIDDLE and spreads OUTWARDS. The order is:
//
//   1. the two centre columns (3 and 4), middle row
//   2. their top and bottom rows, MIRROR_ROW_LAG_DEG behind
//   3. the next ring out (2 and 5), then (1 and 6), then (0 and 7), each
//      MIRROR_COL_LAG_DEG behind the ring inside it
//
// Within a row every clock turns at the same rate, so the offsets picked up on
// the way out are fixed: a standing fan, widest in the middle, never bunching
// and never overtaking. ACROSS rows it is not fixed - the top and bottom run
// slower than the middle (MIRROR_OUTER_RATE), so they drift steadily further
// behind and the three rows beat against one another.
//
// 180 deg of travel returns both hands to the vertical - hand 0 lands where
// hand 1 was - so the figure closes back up and repeats without a seam.
const MIRROR_TURN_S = 9.0;         // 180 deg of hand travel: one open-close
const MIRROR_COL_LAG_DEG = 12.0;   // between one ring and the next one out
const MIRROR_ROW_LAG_DEG = 7.0;   // extra for the top and bottom rows
const MIRROR_RAMP_S = 1.0;         // spin-up, per clock
// The top and bottom rows turn slower than the middle one. They therefore fall
// steadily further behind rather than holding a fixed offset - the rows beat
// against each other, coming back into step every MIRROR_TURN_S / (1 - rate)
// seconds, 36 s at these values.
const MIRROR_OUTER_RATE = 0.75;    // rows 0 and 2, as a fraction of the middle

function tickMirrorWave(cur, t, { modeSpeed }) {
  const rate = 180 / MIRROR_TURN_S;               // deg/s once up to speed
  // Lags are written in DEGREES and converted, so the look is tuned by the
  // angle you want between neighbours rather than by a delay that has to be
  // re-derived whenever the rate changes.
  const colDelay = MIRROR_COL_LAG_DEG / rate;
  const rowDelay = MIRROR_ROW_LAG_DEG / rate;
  const ts = t * modeSpeed;
  const mid = (WALL_COLS - 1) / 2;                // 3.5 on an 8-wide wall

  for (let c = 0; c < NUM_CLOCKS; c++) {
    const { col, row } = wallPos(c);
    // Rings out from the centre: columns 3 and 4 are ring 0, 0 and 7 ring 3.
    const ring = Math.abs(col - mid) - 0.5;
    const x = ts - ring * colDelay - (row === 1 ? 0 : rowDelay);

    // Rows 0 and 2 run slower than row 1 - see MIRROR_OUTER_RATE.
    const r = (row === 1) ? rate : rate * MIRROR_OUTER_RATE;
    let turned;
    if (x <= 0) turned = 0;                                  // not away yet
    else if (x < MIRROR_RAMP_S) turned = r * x * x / (2 * MIRROR_RAMP_S);
    else turned = r * (x - MIRROR_RAMP_S / 2);               // at speed

    // Left half opens right, right half opens left - the mirror. The MIDDLE ROW
    // then scissors the other way from the two around it, so a column reads as
    // three chevrons that alternate rather than three doing the same thing, and
    // the rows shear against each other as they open.
    const sign = (col <= mid ? 1 : -1) * (row === 1 ? -1 : 1);
    cur[c * 2 + 0] = wrap360(0 + sign * turned);
    cur[c * 2 + 1] = wrap360(180 - sign * turned);
  }
}

// -------------------------------------------------------------- test -------
// SANDBOX ONLY - the scratch bench, empty again now that zipper has its own
// name. Nothing depends on it, so overwrite the body freely; when something in
// here is worth keeping, copy it out under its own name and leave this back at
// the neutral pose.
//
// Neutral pose: every clock at 12 and 6, the whole wall uniform and still.
function tickTest(cur) {
  for (let c = 0; c < NUM_CLOCKS; c++) {
    cur[c * 2 + 0] = 0;
    cur[c * 2 + 1] = 180;
  }
}

function tickTime(cur, t, { digits }) {
  for (let d = 0; d < NUM_DIGITS; d++) {
    const val = digits[d];
    const blank = val < 0 || val > 9;
    for (let c = 0; c < CLOCKS_PER_DIGIT; c++)
      for (let h = 0; h < 2; h++)
        cur[(d * CLOCKS_PER_DIGIT + c) * 2 + h] = blank ? PARK : FONT[val][c][h];
  }
}

// A trailing * marks a mode that exists HERE ONLY and is not in the firmware.
// Drop the marker when a mode is ported, or the sandbox starts lying about what
// the wall can actually do.
const MODES = {
  time:        { fn: tickTime,   label: "time",        pose: true  },
  rotate_left: { fn: tickRotate, label: "rotate_left"              },
  birds:       { fn: tickBirds,  label: "birds"                    },
  wave:        { fn: tickWave,   label: "wave"                     },
  spiral:      { fn: tickSpiral, label: "spiral"                   },
  wind:        { fn: tickWind,   label: "wind"                     },
  love:        { fn: tickLove,   label: "love",        pose: true  },
  temp:        { fn: tickTemp,   label: "temp",        pose: true  },
  rotating_maze: { fn: tickRotatingMaze, label: "rotating_maze"      },
  zipper:      { fn: tickZipper, label: "zipper"                   },
  mirror_wave: { fn: tickMirrorWave, label: "mirror_wave"          },
  test:        { fn: tickTest,   label: "test *",      pose: true  },
};

// The firmware's mode names are the WIRE FORMAT and do not all match these
// keys: what it broadcasts as `flying_birds` is `birds` here. Anything reading
// a mode name off a real wall - the Lovelace card, the tablet view - has to go
// through this, or it hands Wall a key that does not exist.
//
// An alias table rather than extra MODES entries: the sandbox builds its mode
// buttons from Object.keys(MODES), and an alias in there is a duplicate button.
const MODE_ALIASES = { flying_birds: "birds" };
const resolveMode = (name) =>
  MODES[name] ? name : (MODE_ALIASES[name] || name);

// Everything the page needs, in one namespace.
window.CC = {
  NUM_DIGITS, CLOCKS_PER_DIGIT, NUM_CLOCKS, NUM_HANDS, WALL_COLS, WALL_ROWS,
  PARK, FONT, LOVE, TEMP_GLYPHS, TG_DEGREE, TG_C, TG_MINUS, TG_BLANK,
  wrap360, shortestDelta, ease, easeOut, wallPos, K, MODES,
  MODE_ALIASES, resolveMode,
  tickRotate, tickBirds, tickWave, tickSpiral, tickWind, tickLove, tickTemp, tickTime,
  tickRotatingMaze, tickZipper, tickMirrorWave, tickTest, cellAt, mazePhase,
};

// ─── wall.js ───────────────────────────────────────────────
// The mode state machine: entry blend, live choreography, settle back to time.
// Ported from LvglClock::blend_into_mode_(), retarget_() and settle_blend_().
//
// This is the part that makes the wall look like an analogue clock rather than
// a display: NOTHING ever jumps. A mode change fades each hand from where it
// was into the choreography, staggered by wall column; leaving one fades the
// remaining offset out while the choreography keeps running underneath.

(function () {
  const C = window.CC;
  const { NUM_HANDS, NUM_DIGITS, CLOCKS_PER_DIGIT, PARK, FONT,
          wrap360, shortestDelta, ease, easeOut, wallPos, MODES, resolveMode } = C;

  const BLEND_NONE = 0, BLEND_PENDING = 1, BLEND_ACTIVE = 2;

  class Wall {
    constructor() {
      this.cur = new Float64Array(NUM_HANDS).fill(PARK);
      this.mode = "time";
      this.modeSpeed = 1.0;
      this.transitionMs = 5000;
      this.staggerMs = C.K.COLUMN_STAGGER_MS;
      this.movement = "opposite";
      this.digits = [1, 2, 3, 4];
      this.temp = 21;

      this.animT = 0;              // choreography time base, seconds
      this.modeStartMs = 0;        // when the current mode was entered

      this.blendState = BLEND_NONE;
      this.blendOff = new Float64Array(NUM_HANDS);
      this.blendStart = 0;

      this.animating = false;      // a time sweep / settle is running
      this.animStart = 0;
      this.start = new Float64Array(NUM_HANDS);
      this.target = new Float64Array(NUM_HANDS);
      this.settleFrom = "time";
      this.settleDelta = new Float64Array(NUM_HANDS);
      this.settlePrev = new Float64Array(NUM_HANDS);
    }

    // How long a full mode entry takes: the sweep plus the column stagger.
    modeEntryLeadS() {
      return (this.transitionMs + (C.WALL_COLS - 1) * this.staggerMs) / 1000;
    }

    setMode(m, nowMs) {
      // A name off a real wall may be the firmware's rather than ours.
      m = resolveMode(m);
      // And an unknown one is REFUSED rather than stored. Storing it meant
      // frame() looked up undefined and threw on every animation frame, which
      // does not stop the loop - it just kills the wall and floods the console.
      if (!MODES[m]) {
        console.warn(`[clockclock24] unknown mode "${m}" - staying on "${this.mode}"`);
        return;
      }
      if (m === this.mode) return;
      if (m === "time") { this.settleToTime(nowMs); return; }
      // Remember where every hand is; blend_into_mode_() converts these to
      // signed offsets on the first frame, once cur[] holds the animation.
      this.blendOff.set(this.cur);
      this.blendState = BLEND_PENDING;
      this.mode = m;
      this.modeStartMs = nowMs;
      this.animT = 0;              // hold the choreography at its start pose
      this.animating = false;
    }

    // ---- retarget_(): work out where every hand has to end up, and how -----
    settleToTime(nowMs) {
      this.settleFrom = this.mode;
      this.mode = "time";
      // The entry blend is deliberately NOT cancelled. A mode can be left
      // before it has finished fading in - a short window, or two mode changes
      // in quick succession - and cur[] currently includes whatever offset is
      // still outstanding. Dropping it makes the very next frame render the
      // raw choreography instead: a jump of exactly that offset, up to 180
      // degrees, which is measurable and was happening.
      for (let d = 0; d < NUM_DIGITS; d++) {
        const val = this.digits[d];
        const blank = val < 0 || val > 9;
        for (let c = 0; c < CLOCKS_PER_DIGIT; c++) {
          for (let h = 0; h < 2; h++) {
            const hi = (d * CLOCKS_PER_DIGIT + c) * 2 + h;
            const goal = blank ? PARK : FONT[val][c][h];
            const base = wrap360(this.cur[hi]);
            this.start[hi] = base;
            let cw = (goal - base) % 360;
            if (cw < 0) cw += 360;
            const ccw = cw - 360;
            let delta;
            if (cw < 0.001) {
              delta = 0;
            } else if (this.settleFrom !== "time") {
              // Leaving a choreography: ALWAYS the shortest way round,
              // whatever `movement:` says. The hands are already moving, and
              // `long` would run them at ~4x the choreography's own rate.
              delta = cw <= 180 ? cw : ccw;
            } else {
              switch (this.movement) {
                case "clockwise": delta = cw; break;
                case "counter":   delta = ccw; break;
                case "long":      delta = cw >= 180 ? cw : ccw; break;
                default:          delta = h === 0 ? cw : ccw; break;   // opposite
              }
            }
            this.target[hi] = base + delta;
          }
        }
      }
      this.animStart = nowMs;
      this.animating = true;
      if (this.settleFrom !== "time") {
        for (let i = 0; i < NUM_HANDS; i++) {
          this.settlePrev[i] = this.start[i];
          this.settleDelta[i] = this.target[i] - this.start[i];
        }
      }
    }

    // A digit change while showing the time: an ordinary eased sweep.
    setDigits(digits, nowMs) {
      this.digits = digits;
      if (this.mode === "time") { this.settleFrom = "time"; this.settleToTime(nowMs); }
    }

    // ---- blend_into_mode_() -----------------------------------------------
    blendIntoMode(nowMs) {
      if (this.blendState === BLEND_NONE) return;
      if (this.blendState === BLEND_PENDING) {
        // Measured ONCE, so the direction can never flip sign mid-fade.
        for (let i = 0; i < NUM_HANDS; i++)
          this.blendOff[i] = shortestDelta(this.cur[i], this.blendOff[i]);
        this.blendStart = nowMs;
        this.blendState = BLEND_ACTIVE;
      }
      const elapsed = nowMs - this.blendStart;
      let allDone = true;
      for (let i = 0; i < NUM_HANDS; i++) {
        const { col } = wallPos(i >> 1);
        const delay = col * this.staggerMs;
        let k;
        if (this.transitionMs === 0) k = 0;
        else if (elapsed <= delay) { k = 1; allDone = false; }
        else {
          const t = (elapsed - delay) / this.transitionMs;
          if (t >= 1) k = 0;
          else { k = 1 - ease(t); allDone = false; }
        }
        if (k !== 0) this.cur[i] = wrap360(this.cur[i] + this.blendOff[i] * k);
      }
      if (allDone) this.blendState = BLEND_NONE;
      return !allDone;
    }

    // ---- settle_blend_(): the choreography keeps running underneath -------
    settleBlend(nowMs) {
      const elapsed = nowMs - this.animStart;
      let allDone = true;
      for (let i = 0; i < NUM_HANDS; i++) {
        const anim = this.cur[i];
        // delta is carried forward and reduced by the animation's own
        // movement, so `anim + delta` stays pinned on the target throughout.
        this.settleDelta[i] -= shortestDelta(this.settlePrev[i], anim);
        this.settlePrev[i] = anim;

        const { col } = wallPos(i >> 1);
        const delay = col * this.staggerMs;
        let w;
        if (this.transitionMs === 0) w = 1;
        else if (elapsed <= delay) { w = 0; allDone = false; }
        else {
          const t = (elapsed - delay) / this.transitionMs;
          if (t >= 1) w = 1;
          else { w = easeOut(t); allDone = false; }
        }
        this.cur[i] = wrap360(anim + this.settleDelta[i] * w);
      }
      if (allDone) { this.animating = false; this.settleFrom = "time"; }
      return !allDone;
    }

    // A plain eased sweep, for a digit change with no choreography behind it.
    plainSweep(nowMs) {
      const elapsed = nowMs - this.animStart;
      let allDone = true;
      for (let i = 0; i < NUM_HANDS; i++) {
        const { col } = wallPos(i >> 1);
        const delay = col * this.staggerMs;
        let t;
        if (this.transitionMs === 0) t = 1;
        else if (elapsed <= delay) { t = 0; allDone = false; }
        else {
          t = (elapsed - delay) / this.transitionMs;
          if (t >= 1) t = 1; else allDone = false;
        }
        this.cur[i] = wrap360(this.start[i] + (this.target[i] - this.start[i]) * ease(t));
      }
      if (allDone) this.animating = false;
      return !allDone;
    }

    // ---- one frame ---------------------------------------------------------
    frame(nowMs, dtS) {
      const settling = this.animating && this.settleFrom !== "time";
      const live = settling ? this.settleFrom : this.mode;
      // Belt and braces: setMode refuses unknown modes, so this can only fire
      // if something set .mode directly. Showing the time beats throwing.
      const spec = MODES[live] || MODES.time;

      // The choreography clock is HELD AT 0 until the entry blend finishes, so
      // the blend chases a STILL target. Without this every hand fades toward
      // a moving pose and the wall never starts uniform — which is exactly the
      // "wind doesn't start with all hands in the same place" bug.
      //
      // Once we are settling OUT of a mode, the choreography has to keep
      // running underneath, or the wall freezes and then sweeps instead of
      // winding down out of the movement.
      if (this.blendState === BLEND_NONE || settling) this.animT += dtS;

      spec.fn(this.cur, this.animT, {
        modeSpeed: this.modeSpeed, digits: this.digits, temp: this.temp,
      });

      // Applied BEFORE the settle, so an entry blend that is still outstanding
      // keeps fading on top of the choreography rather than vanishing.
      const blending = this.blendState !== BLEND_NONE ? this.blendIntoMode(nowMs) : false;

      if (settling) return this.settleBlend(nowMs) || blending;
      if (blending) return true;
      if (this.animating) return this.plainSweep(nowMs);
      return false;
    }
  }

  window.CC.Wall = Wall;
})();

// ─── pattern.js ───────────────────────────────────────────────
// The pattern editor's model: a per-clock motion spec, and the mode that draws
// it. Loaded as a classic script after engine.js.
//
// A pattern is 24 entries, one per clock:
//
//   { h0, h1,      the HOME pose - what you configured, in degrees
//     a0, a1,      the runtime ANCHOR the motion is measured from
//     dirA, dirB,  -1 left (counter-clockwise), 0 still, +1 right
//     spdA, spdB } speed, 0..1 of PATTERN_MAX_RATE
//
// HOME and ANCHOR are separate on purpose. The anchor moves constantly: every
// time a speed or direction is edited it has to be re-cut so the hands do not
// jump (see rebaseAll in the page). If that were the only stored pose, the
// thing you configured would be quietly overwritten the first time you touched
// a slider, and there would be nothing left to go back to.
//
// So: dragging a hand sets BOTH - you are configuring a new pose. Everything
// else moves the anchor only, and `toHome()` puts the hands back on the pose
// you actually chose.
//
// A speed is either FIXED - {mode:"fixed", v} - or RELATIVE to a neighbour's
// speed for the same hand: {mode:"rel", from:"left"|"right"|"up"|"down", d}.
// Relative speeds are what make a pattern a pattern rather than 24 unrelated
// clocks: set one clock going and let the wall derive itself from it.

(function () {
  const C = window.CC;
  const { NUM_CLOCKS, WALL_COLS, WALL_ROWS, wallPos, wrap360 } = C;

  // Speed 1.0 in degrees per second. One full turn in 4 s at full tilt - fast
  // enough to be unmistakable, slow enough to stay an analogue clock.
  const PATTERN_MAX_RATE = 90;

  const clamp01 = v => Math.max(0, Math.min(1, v));
  const fixed = v => ({ mode: "fixed", v });

  function blank() {
    const spec = [];
    for (let i = 0; i < NUM_CLOCKS; i++)
      spec.push({ h0: 0, h1: 180, a0: 0, a1: 180,
                  dirA: 0, dirB: 0, spdA: fixed(0.3), spdB: fixed(0.3) });
    return spec;
  }
  let spec = blank();

  // The clock one step away in a given direction, or null at the wall's edge.
  function neighbour(i, dir) {
    const { col, row } = wallPos(i);
    let c = col, r = row;
    if (dir === "left") c--; else if (dir === "right") c++;
    else if (dir === "up") r--; else if (dir === "down") r++;
    if (c < 0 || c >= WALL_COLS || r < 0 || r >= WALL_ROWS) return null;
    return (c >> 1) * C.CLOCKS_PER_DIGIT + r * 2 + (c & 1);
  }

  // Resolve a speed, following "same as my neighbour" chains.
  //
  // The chain can loop - A takes B's speed and B takes A's - so `seen` breaks
  // the cycle at 0 rather than recursing forever. A cycle is a user mistake,
  // not a crash, and the clock simply stops.
  function speedOf(i, hand, seen) {
    const sp = spec[i][hand === 0 ? "spdA" : "spdB"];
    if (sp.mode === "fixed") return clamp01(sp.v);
    const key = i * 2 + hand;
    if (seen.has(key)) return 0;
    seen.add(key);
    const j = neighbour(i, sp.from);
    if (j === null) return 0;                    // off the edge: nothing to copy
    return clamp01(speedOf(j, hand, seen) + sp.d);
  }

  function resolved() {
    const out = [];
    for (let i = 0; i < NUM_CLOCKS; i++)
      out.push([speedOf(i, 0, new Set()), speedOf(i, 1, new Set())]);
    return out;
  }

  // Every hand is base + direction * speed * rate * t: continuous by
  // construction, so a pattern can never jump however it is edited.
  function tickPattern(cur, t, { modeSpeed }) {
    const ts = t * modeSpeed;
    const sp = resolved();
    for (let i = 0; i < NUM_CLOCKS; i++) {
      const s = spec[i];
      cur[i * 2 + 0] = wrap360(s.a0 + s.dirA * sp[i][0] * PATTERN_MAX_RATE * ts);
      cur[i * 2 + 1] = wrap360(s.a1 + s.dirB * sp[i][1] * PATTERN_MAX_RATE * ts);
    }
  }

  const clone = s => JSON.parse(JSON.stringify(s));

  window.CC.pattern = {
    MAX_RATE: PATTERN_MAX_RATE,
    get: i => spec[i],
    all: () => spec,
    resolved,
    neighbour,
    reset: () => { spec = blank(); },
    // How far a hand has been carried from its pose by time `ts`.
    offsetAt(i, hand, ts) {
      const s = spec[i];
      const dir = hand === 0 ? s.dirA : s.dirB;
      return dir * speedOf(i, hand, new Set()) * PATTERN_MAX_RATE * ts;
    },
    // Cut the ANCHOR so the hand is AT `angle` right now, rather than at t = 0.
    //
    // With the motion running, storing an angle straight into the anchor would
    // make the hand snap to wherever the motion has carried it - you would be
    // aiming at a moving target. Subtracting the offset means the hand lands
    // where you put it and carries on from there.
    //
    // This does NOT touch the home pose: it is the continuity fix, not an edit.
    anchorAt(i, hand, angle, ts) {
      const a = wrap360(angle - this.offsetAt(i, hand, ts));
      if (hand === 0) spec[i].a0 = a; else spec[i].a1 = a;
    },
    // Configure a hand: this IS an edit, so it sets the home pose as well.
    setHomeAt(i, hand, angle, ts) {
      const a = wrap360(angle);
      if (hand === 0) spec[i].h0 = a; else spec[i].h1 = a;
      this.anchorAt(i, hand, a, ts);
    },
    // Put every hand back on the pose it was configured with, still running.
    toHome(ts) {
      for (let i = 0; i < NUM_CLOCKS; i++) {
        this.anchorAt(i, 0, spec[i].h0, ts || 0);
        this.anchorAt(i, 1, spec[i].h1, ts || 0);
      }
    },
    // Take the wall's current angles as the pattern's home pose, so anything
    // posed by hand or left behind by another mode can be a starting point.
    seedFrom(cur, ts) {
      for (let i = 0; i < NUM_CLOCKS; i++) {
        this.setHomeAt(i, 0, cur[i * 2 + 0], ts || 0);
        this.setHomeAt(i, 1, cur[i * 2 + 1], ts || 0);
      }
    },
    copy: i => clone(spec[i]),
    paste(i, src) { spec[i] = clone(src); },
    pasteAll(src) { for (let i = 0; i < NUM_CLOCKS; i++) spec[i] = clone(src); },
    pasteRow(row, src) {
      for (let i = 0; i < NUM_CLOCKS; i++) if (wallPos(i).row === row) spec[i] = clone(src);
    },
    pasteCol(col, src) {
      for (let i = 0; i < NUM_CLOCKS; i++) if (wallPos(i).col === col) spec[i] = clone(src);
    },
    // The whole configuration - home pose and motion, per clock - as JSON that
    // fromJSON() can read back.
    toJSON() {
      const r = v => Math.round(v * 100) / 100;
      return JSON.stringify({
        format: "clockclock24-pattern",
        version: 1,
        maxRateDegPerS: PATTERN_MAX_RATE,
        clocks: spec.map(s => ({
          h0: Math.round(s.h0), h1: Math.round(s.h1),
          dirA: s.dirA, dirB: s.dirB,
          spdA: s.spdA.mode === "fixed"
            ? { mode: "fixed", v: r(s.spdA.v) }
            : { mode: "rel", from: s.spdA.from, d: r(s.spdA.d) },
          spdB: s.spdB.mode === "fixed"
            ? { mode: "fixed", v: r(s.spdB.v) }
            : { mode: "rel", from: s.spdB.from, d: r(s.spdB.d) },
        })),
      }, null, 1);
    },

    // The form an ESPHome text entity takes: "<name>:<base64>".
    //
    // A pattern as JSON is ~5 kB and a Home Assistant text entity holds 255
    // characters, so this is packed - five bytes per clock, mirroring
    // PatternStore::to_text() in the firmware:
    //
    //   0  h0, in 1.5 deg steps (0..239)     3  v0, 0..100
    //   1  h1                                 4  v1
    //   2  (dir0+1) << 2 | (dir1+1)
    //
    // 24 x 5 = 120 bytes = 160 base64 chars. The 1.5 deg quantisation is ten
    // times finer than the editor's 15 deg snap, so nothing authored is lost.
    //
    // Relative speeds are RESOLVED first: the firmware only ever sees numbers.
    toESPHome(name) {
      const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
      const sp = this.resolved();
      const buf = new Uint8Array(NUM_CLOCKS * 5);
      for (let i = 0; i < NUM_CLOCKS; i++) {
        const s = spec[i], b = i * 5;
        buf[b + 0] = Math.round(wrap360(s.h0) / 1.5) % 240;
        buf[b + 1] = Math.round(wrap360(s.h1) / 1.5) % 240;
        buf[b + 2] = ((s.dirA + 1) << 2) | (s.dirB + 1);
        buf[b + 3] = Math.round(sp[i][0] * 100);
        buf[b + 4] = Math.round(sp[i][1] * 100);
      }
      let out = "";
      for (let i = 0; i < buf.length; i += 3) {
        const v = (buf[i] << 16) | ((buf[i + 1] || 0) << 8) | (buf[i + 2] || 0);
        out += B64[(v >> 18) & 63] + B64[(v >> 12) & 63] +
               (i + 1 < buf.length ? B64[(v >> 6) & 63] : "=") +
               (i + 2 < buf.length ? B64[v & 63] : "=");
      }
      return (name || "pattern").slice(0, 15) + ":" + out;
    },

    // The inverse of toESPHome(): unpack "<name>:<base64>" into 24 clock specs.
    //
    // Returns { name, clocks } or null. Used by the Home Assistant card, which
    // takes the SAME string that goes into a Pattern text entity - one format
    // for the hardware and the browser, so a pattern you like can be dropped
    // into either.
    parseESPHome(text) {
      const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
      if (typeof text !== "string" || !text) return null;
      const colon = text.indexOf(":");
      const name = colon >= 0 ? text.slice(0, colon) : "pattern";
      const data = colon >= 0 ? text.slice(colon + 1) : text;

      const bytes = [];
      let acc = 0, bits = 0;
      for (const ch of data) {
        if (ch === "=" || ch === "\n" || ch === "\r" || ch === " ") continue;
        const v = B64.indexOf(ch);
        if (v < 0) return null;
        acc = (acc << 6) | v; bits += 6;
        if (bits >= 8) { bits -= 8; bytes.push((acc >> bits) & 0xff); }
      }
      if (bytes.length !== NUM_CLOCKS * 5) return null;

      const clocks = [];
      for (let i = 0; i < NUM_CLOCKS; i++) {
        const b = i * 5;
        clocks.push({
          h0: (bytes[b] * 3) / 2 % 360,
          h1: (bytes[b + 1] * 3) / 2 % 360,
          dir0: ((bytes[b + 2] >> 2) & 3) - 1,
          dir1: (bytes[b + 2] & 3) - 1,
          v0: Math.min(100, bytes[b + 3]) / 100,
          v1: Math.min(100, bytes[b + 4]) / 100,
        });
      }
      return { name, clocks };
    },

    // Read a configuration back. Returns null on success, or a message.
    //
    // Everything is validated and coerced rather than trusted: this is text a
    // human has been editing, and a bad field should cost you one wrong clock,
    // not a wall of NaN that silently draws nothing.
    fromJSON(text, ts) {
      let o;
      try { o = JSON.parse(text); } catch (e) { return "not valid JSON — " + e.message; }
      const list = Array.isArray(o) ? o : (o && o.clocks);
      if (!Array.isArray(list)) return "no `clocks` array in there";
      if (list.length !== NUM_CLOCKS) return `expected ${NUM_CLOCKS} clocks, found ${list.length}`;

      const DIRS = ["left", "right", "up", "down"];
      const num = (v, dflt) => (Number.isFinite(+v) ? +v : dflt);
      const readSpeed = raw => {
        if (!raw || typeof raw !== "object") return fixed(0.3);
        if (raw.mode === "rel")
          return { mode: "rel",
                   from: DIRS.indexOf(raw.from) >= 0 ? raw.from : "left",
                   d: Math.max(-1, Math.min(1, num(raw.d, 0))) };
        return fixed(clamp01(num(raw.v, 0.3)));
      };

      const next = blank();
      for (let i = 0; i < NUM_CLOCKS; i++) {
        const c = list[i] || {};
        next[i].h0 = wrap360(num(c.h0, 0));
        next[i].h1 = wrap360(num(c.h1, 180));
        next[i].dirA = Math.sign(num(c.dirA, 0));
        next[i].dirB = Math.sign(num(c.dirB, 0));
        next[i].spdA = readSpeed(c.spdA);
        next[i].spdB = readSpeed(c.spdB);
      }
      spec = next;
      this.toHome(ts || 0);      // start from the loaded poses, not from t = 0
      return null;
    },

  };
  window.CC.tickPattern = tickPattern;
  // No sandbox-only marker on this one: an editor is not a thing that could
  // ever be ported to the firmware, so the note would be telling you nothing.
  window.CC.MODES.pattern = { fn: tickPattern, label: "Motion Pattern Editor Mode" };
})();

// ─── card.js ───────────────────────────────────────────────
// ClockClock 24 — a Lovelace card.
//
// Renders the wall in Home Assistant using the SAME engine as the firmware and
// the sandbox. engine.js, wall.js and pattern.js are prepended to this file by
// build.sh rather than copied into it, so there is one implementation of a
// choreography, not three.
//
// It also eats the sandbox's pattern strings: the exact text you paste into a
// `Pattern` entity to drive the real wall will drive this card too.

(function () {
  const C = window.CC;
  if (!C) { console.error("[clockclock24-card] engine missing — rebuild with build.sh"); return; }

  const CARD_VERSION = "0.1.0";
  console.info(`%c CLOCKCLOCK24-CARD %c ${CARD_VERSION} `,
               "color:#000;background:#6ea8fe;font-weight:700",
               "color:#6ea8fe;background:#222");

  const DEFAULTS = {
    mode: "cycle",              // a mode name, "cycle", or "pattern"
    cycle: ["wave", "wind", "rotating_maze", "zipper", "mirror_wave", "spiral"],
    cycle_interval: 60,         // seconds between windows
    window: 35,                 // seconds of choreography per window
    return_to_time: true,       // …then back to the clock until the next one
    transition: 5000,           // ms for a sweep, and for the fade into a mode
    mode_speed: 1.0,
    // How the two hands travel to a new digit, same names as the firmware.
    // wall.js has always honoured this; it was simply never in the config.
    movement: "opposite",       // opposite | clockwise | counter | long
    hand_color: "#ffffff",
    background: "#000000",
    face_color: "#1f1f23",
    show_face: false,
    // 0 = the real wall: 24 panels on one frame, evenly spaced. Raise it for a
    // dashboard card if you want the HH:MM grouping to read at a glance.
    digit_gap: 0,               // extra space between digits, in clock widths
    fullscreen: false,          // fill the viewport height instead of flowing
    pattern: null,              // "<name>:<base64>" from the sandbox
    time_entity: null,          // optional; default is the browser's clock
  };

  class ClockClock24Card extends HTMLElement {
    setConfig(config) {
      this._cfg = Object.assign({}, DEFAULTS, config || {});
      if (typeof this._cfg.cycle === "string") this._cfg.cycle = [this._cfg.cycle];

      // A pattern is decoded once, here, rather than every frame.
      this._pattern = null;
      if (this._cfg.pattern) {
        this._pattern = C.pattern.parseESPHome(this._cfg.pattern);
        if (!this._pattern)
          throw new Error("clockclock24-card: `pattern` is not a pattern string from the sandbox");
      }
      if (this._cfg.mode === "pattern" && !this._pattern)
        throw new Error("clockclock24-card: mode `pattern` needs a `pattern:` string");

      this._build();
    }

    // Home Assistant hands the card its state object on every update. Nothing
    // here needs it unless a time_entity was named - the wall runs off the
    // browser clock, which is already correct and costs no round trips.
    set hass(hass) { this._hass = hass; }

    getCardSize() { return this._cfg && this._cfg.fullscreen ? 10 : 4; }

    static getStubConfig() { return { type: "custom:clockclock24-card", mode: "cycle" }; }

    connectedCallback() { this._start(); }
    disconnectedCallback() { this._stop(); }

    // ---- setup -------------------------------------------------------------
    _build() {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      const cfg = this._cfg;
      this.shadowRoot.innerHTML = `
        <style>
          :host { display: block; }
          /* display:block explicitly. Inside Lovelace ha-card is a defined
             element and already block, but in the add-on's tablet view it is
             UNDEFINED - and an unknown element defaults to display:inline, so
             the canvas's width:100% resolves against a shrink-to-fit inline
             box and the wall collapses to nothing. */
          ha-card { display: block; overflow: hidden; }
          .wrap { background: ${cfg.background}; }
          canvas {
            display: block; width: 100%; height: auto;
            aspect-ratio: ${8 + cfg.digit_gap * 3} / 3;
          }
          :host([data-fullscreen]) canvas {
            height: 100vh; width: 100%; object-fit: contain; aspect-ratio: auto;
          }
        </style>
        <ha-card><div class="wrap"><canvas></canvas></div></ha-card>`;
      if (cfg.fullscreen) this.setAttribute("data-fullscreen", "");
      this._canvas = this.shadowRoot.querySelector("canvas");
      this._ctx = this._canvas.getContext("2d");

      this._wall = new C.Wall();
      this._wall.transitionMs = cfg.transition;
      this._wall.modeSpeed = cfg.mode_speed;
      this._wall.movement = cfg.movement;
      this._pushTime(performance.now());

      // Fixed mode, or the rotation.
      this._cycleAt = -1;
      this._nextWindow = 0;
      this._inWindow = false;
      if (cfg.mode !== "cycle") this._wall.setMode(this._modeFor(cfg.mode), performance.now());
    }

    // Change what is showing on the LIVE card.
    //
    // setConfig() rebuilds everything, which throws away where the hands are -
    // and this card exists to be an analogue clock, so it cannot jump. Anything
    // following a real wall must come through here instead.
    setMode(name, pattern) {
      if (pattern !== undefined && pattern !== this._cfg.pattern) {
        this._cfg.pattern = pattern;
        this._pattern = pattern ? C.pattern.parseESPHome(pattern) : null;
        this._patternLoaded = false;
      }
      if (name === this._cfg.mode && name !== "pattern") return;
      this._cfg.mode = name;
      this._cycleAt = -1;
      this._inWindow = false;
      if (name === "cycle") { this._nextWindow = 0; return; }
      this._wall.setMode(this._modeFor(name), performance.now());
    }

    // Colours, live. Same reason as setMode: rebuilding to recolour would
    // restart the animation, and the hands would jump.
    setColors(hand, background) {
      if (hand) this._cfg.hand_color = hand;
      if (background) {
        this._cfg.background = background;
        const wrap = this.shadowRoot && this.shadowRoot.querySelector(".wrap");
        if (wrap) wrap.style.background = background;
      }
    }

    // `pattern` is drawn by the pattern mode, which reads the decoded spec.
    _modeFor(name) {
      if (name !== "pattern") return name;
      this._loadPattern();
      return "pattern";
    }

    _loadPattern() {
      if (!this._pattern || this._patternLoaded) return;
      this._pattern.clocks.forEach((c, i) => {
        const s = C.pattern.get(i);
        s.h0 = c.h0; s.h1 = c.h1;
        s.dirA = c.dir0; s.dirB = c.dir1;
        s.spdA = { mode: "fixed", v: c.v0 };
        s.spdB = { mode: "fixed", v: c.v1 };
      });
      C.pattern.toHome(0);
      this._patternLoaded = true;
    }

    _pushTime(now) {
      let d = new Date();
      const ent = this._cfg.time_entity && this._hass && this._hass.states[this._cfg.time_entity];
      if (ent && !isNaN(Date.parse(ent.state))) d = new Date(ent.state);
      const hh = d.getHours(), mm = d.getMinutes();
      const digits = [Math.floor(hh / 10), hh % 10, Math.floor(mm / 10), mm % 10];
      if (this._digits && digits.every((v, i) => v === this._digits[i])) return;
      this._digits = digits;
      this._wall.setDigits(digits, now);
    }

    // ---- the loop ----------------------------------------------------------
    _start() {
      if (this._raf) return;
      this._last = performance.now();
      const tick = (t) => {
        this._raf = requestAnimationFrame(tick);
        // Clamped: a card on a background tab must not leap when it wakes.
        const dt = Math.min((t - this._last) / 1000, 0.1);
        this._last = t;
        this._advance(t);
        this._wall.frame(t, dt);
        this._render();
      };
      this._raf = requestAnimationFrame(tick);
    }
    _stop() { if (this._raf) cancelAnimationFrame(this._raf); this._raf = null; }

    // The same shape as the firmware's cycle_modes: a window opens every
    // `cycle_interval`, runs for `window` seconds, then the clock comes back.
    _advance(t) {
      const cfg = this._cfg;
      if (cfg.mode !== "cycle") { this._pushTime(t); return; }
      if (!cfg.cycle.length) return;

      if (!this._inWindow && t >= this._nextWindow) {
        this._cycleAt = (this._cycleAt + 1) % cfg.cycle.length;
        const m = this._modeFor(cfg.cycle[this._cycleAt]);
        if (C.MODES[m]) this._wall.setMode(m, t);
        this._inWindow = true;
        this._windowEnds = t + cfg.window * 1000;
        this._nextWindow = t + cfg.cycle_interval * 1000;
      } else if (this._inWindow && t >= this._windowEnds) {
        this._inWindow = false;
        if (cfg.return_to_time) {
          // Digits FIRST, then leave the mode: settleToTime() reads
          // wall.digits to work out where every hand is going, and setDigits()
          // is a no-op while a choreography is running (it only settles when
          // the mode is already `time`). Pushing digits without this left the
          // wall animating for ever; leaving the mode without it settled to
          // whatever minute was last shown.
          this._digits = null;
          this._pushTime(t);
          this._wall.setMode("time", t);
        }
      }
      if (!this._inWindow) this._pushTime(t);
    }

    // ---- drawing -----------------------------------------------------------
    _render() {
      const cfg = this._cfg, cv = this._canvas, ctx = this._ctx;
      // Match the backing store to the CSS box so the hands stay crisp on a
      // retina display and do not blur when the card is resized.
      const rect = cv.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      const w = Math.max(1, Math.round(rect.width * dpr));
      const h = Math.max(1, Math.round(rect.height * dpr));
      if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }

      ctx.fillStyle = cfg.background;
      ctx.fillRect(0, 0, w, h);

      const gapCols = cfg.digit_gap * 3;
      const cell = Math.min(w / (C.WALL_COLS + gapCols), h / C.WALL_ROWS);
      const gap = cell * cfg.digit_gap;
      const r = cell * 0.46;
      const totalW = cell * C.WALL_COLS + gap * 3;
      const x0 = (w - totalW) / 2 + cell / 2;
      const y0 = (h - cell * C.WALL_ROWS) / 2 + cell / 2;
      const lw = Math.max(1, r / 8);

      for (let c = 0; c < C.NUM_CLOCKS; c++) {
        const p = C.wallPos(c);
        const cx = x0 + p.col * cell + Math.floor(p.col / 2) * gap;
        const cy = y0 + p.row * cell;
        if (cfg.show_face) {
          ctx.fillStyle = cfg.face_color;
          ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
        }
        ctx.strokeStyle = cfg.hand_color;
        ctx.fillStyle = cfg.hand_color;
        ctx.lineWidth = lw;
        ctx.lineCap = "butt";
        for (const a of [this._wall.cur[c * 2], this._wall.cur[c * 2 + 1]]) {
          const rad = (a - 90) * Math.PI / 180;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + Math.cos(rad) * r, cy + Math.sin(rad) * r);
          ctx.stroke();
        }
        // Rounded pivot, square tips - the ClockClock look.
        ctx.beginPath(); ctx.arc(cx, cy, lw / 2, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  customElements.define("clockclock24-card", ClockClock24Card);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: "clockclock24-card",
    name: "ClockClock 24",
    description: "A digital clock made of 24 analogue ones, with the wall's own choreographies.",
    preview: true,
  });
})();

// ─── editor-card.js ───────────────────────────────────────────────
// ClockClock 24 — pattern editor card.
//
// The sandbox's Motion Pattern Editor, as a Lovelace card, wired to the wall:
// draw a pattern, watch it run, and press Send to write it into the ESPHome
// `Pattern N` text entity. The master pushes it down the sync bus and 24 real
// clocks are running it a second later.
//
// It shares the engine and the pattern model with the clock card - both are in
// the same bundle - so the preview here is not an approximation of the wall, it
// is the wall's own code with a canvas instead of panels.

(function () {
  const C = window.CC;
  if (!C) { console.error("[clockclock24-editor-card] engine missing — rebuild with build.sh"); return; }
  const P = C.pattern;

  const MAX_RATE = P.MAX_RATE;
  // Speed sliders are SQUARED: a linear travel spends nine tenths of itself
  // above 9 deg/s, and the slow end is where a pattern reads. The slider is in
  // PERCENT with a 0.5 step, so the readout is a number you can dial back to
  // rather than a position you have to find again by eye.
  const ICON_PAUSE = '<svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">' +
    '<rect x="2" y="1.5" width="3" height="9" fill="currentColor"/>' +
    '<rect x="7" y="1.5" width="3" height="9" fill="currentColor"/></svg>';
  const ICON_PLAY = '<svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">' +
    '<path d="M3 1.5 L10.5 6 L3 10.5 Z" fill="currentColor"/></svg>';

  const spdFromSlider = pct => { const p = pct / 100; return p * p; };
  const sliderFromSpd = v => Math.sqrt(Math.max(0, v)) * 100;

  class ClockClock24EditorCard extends HTMLElement {
    setConfig(cfg) {
      this._cfg = Object.assign({ entity: null, snap: 15, name: "pattern" }, cfg || {});
      this._sel = new Set([0]);
      this._primary = 0;
      this._scope = "all";       // what Copy carries: all | position | motion
      this._clip = null;
      this._build();
    }
    set hass(h) { this._hass = h; if (this._entityRow) this._syncEntity(); }
    getCardSize() { return 8; }
    static getStubConfig() { return { type: "custom:clockclock24-editor-card" }; }

    connectedCallback() { this._start(); }
    disconnectedCallback() { this._stop(); }

    _build() {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      this.shadowRoot.innerHTML = `
        <style>
          :host { display:block; }
          canvas { display:block; width:100%; height:auto; aspect-ratio:8/3; background:#000; cursor:crosshair; }
          .pad { padding: 12px 16px 16px; }
          .row { display:flex; gap:6px; align-items:center; flex-wrap:wrap; margin-top:8px; }
          .row > .lbl { min-width:4.5em; opacity:.7; font-size:.85em; }
          button { font:inherit; padding:4px 9px; border-radius:6px; cursor:pointer;
                   border:1px solid var(--divider-color,#444);
                   background:var(--secondary-background-color,#222);
                   color:var(--primary-text-color,#eee); }
          button[aria-pressed="true"] { background:var(--primary-color,#03a9f4); color:#000; font-weight:600; }
          button:disabled { opacity:.4; cursor:not-allowed; }
          input[type=range] { flex:1 1 90px; min-width:80px; }
          select { font:inherit; padding:3px 6px; border-radius:6px;
                   border:1px solid var(--divider-color,#444);
                   background:var(--secondary-background-color,#222);
                   color:var(--primary-text-color,#eee); }
          .row.rel { margin-top:2px; opacity:.9; }
          .pm { opacity:.6; }
          .val { min-width:9.5em; text-align:right; font-variant-numeric:tabular-nums; font-size:.85em; }
          .hint { margin:8px 0 0; font-size:.8em; opacity:.7; }
          /* Holding something is a state you should be able to see without
             reading - the dot is the same one the wall panel marks patterns
             with. */
          .hint.held { opacity:1; color:var(--primary-color,#03a9f4); }
          .hint.held::before {
            content:""; display:inline-block; width:5px; height:5px;
            border-radius:50%; background:currentColor; margin-right:6px;
            vertical-align:middle;
          }
          .hint.inline { margin:0; }
          .sec { margin:16px 0 2px; font-size:.72em; letter-spacing:.09em;
                 text-transform:uppercase; opacity:.55; font-weight:600;
                 border-top:1px solid var(--divider-color,#333); padding-top:10px;
                 display:flex; gap:8px; align-items:baseline; flex-wrap:wrap; }
          .sec:first-of-type { border-top:0; margin-top:6px; padding-top:0; }
          .secnote { text-transform:none; letter-spacing:0; font-weight:400; opacity:.8; }
          button.icon { line-height:0; padding:6px 11px; }
          button.icon svg { display:block; }
          /* Hovering a clock says what it is set to - the canvas cannot carry
             text, and reading a pattern off 24 pairs of hands is guesswork. */
          .tip { position:absolute; pointer-events:none; z-index:5; display:none;
                 background:#0e1013ee; color:#e7e9ee; border:1px solid #2a2f37;
                 border-radius:6px; padding:6px 9px; font:11px/1.45 ui-monospace,monospace;
                 white-space:pre; transform:translate(-50%,-115%); }
          .cvwrap { position:relative; }
          textarea { width:100%; margin-top:8px; min-height:60px; font:11px/1.4 ui-monospace,monospace;
                     background:#0e1013; color:#8fd0a0; border:1px solid var(--divider-color,#444);
                     border-radius:6px; padding:6px; }
        </style>
        <ha-card>
          <div class="cvwrap"><canvas></canvas><div class="tip" id="tip"></div></div>
          <div class="pad">
            <p class="hint" id="who"></p>

            <div class="sec">Selection</div>
            <div class="row">
              <span class="lbl">select</span>
              <button id="selall">All 24</button>
              <button id="selrow">Row</button>
              <button id="selcol">Column</button>
              <button id="selnone">Just one</button>
              <span class="hint inline">or shift-click the wall</span>
            </div>

            <div class="row"><span class="lbl">hand A</span>
              <button class="dir" data-h="0" data-v="-1" title="counter-clockwise">&#8634;</button>
              <button class="dir" data-h="0" data-v="0" title="still">&#9679;</button>
              <button class="dir" data-h="0" data-v="1" title="clockwise">&#8635;</button>
              <select id="mode0" title="Fixed rate, or take a neighbour's and add to it">
                <option value="fixed">fixed</option>
                <option value="rel">same as…</option>
              </select>
              <input type="range" id="spd0" min="0" max="100" step="0.5">
              <span class="val" id="spd0v"></span>
            </div>
            <div class="row rel" id="rel0" style="display:none">
              <span class="lbl"></span>
              <select id="from0">
                <option value="left">the clock to its left</option>
                <option value="right">to its right</option>
                <option value="up">above it</option>
                <option value="down">below it</option>
              </select>
              <span class="pm">±</span>
              <input type="range" id="d0" min="-50" max="50" step="0.5">
              <span class="val" id="d0v"></span>
            </div>
            <div class="row"><span class="lbl">hand B</span>
              <button class="dir" data-h="1" data-v="-1" title="counter-clockwise">&#8634;</button>
              <button class="dir" data-h="1" data-v="0" title="still">&#9679;</button>
              <button class="dir" data-h="1" data-v="1" title="clockwise">&#8635;</button>
              <select id="mode1" title="Fixed rate, or take a neighbour's and add to it">
                <option value="fixed">fixed</option>
                <option value="rel">same as…</option>
              </select>
              <input type="range" id="spd1" min="0" max="100" step="0.5">
              <span class="val" id="spd1v"></span>
            </div>
            <div class="row rel" id="rel1" style="display:none">
              <span class="lbl"></span>
              <select id="from1">
                <option value="left">the clock to its left</option>
                <option value="right">to its right</option>
                <option value="up">above it</option>
                <option value="down">below it</option>
              </select>
              <span class="pm">±</span>
              <input type="range" id="d1" min="-50" max="50" step="0.5">
              <span class="val" id="d1v"></span>
            </div>

            <div class="row">
              <span class="lbl">pose</span>
              <button id="home" title="Put all 24 clocks back on the pose you configured">Back to pose</button>
              <button id="seed" title="Freeze where the selected hands are NOW as their pose">Wall to pose</button>
            </div>

          <div class="sec">Copy<span class="secnote">from the primary clock to every selected one</span></div>
            <div class="row">
              <span class="lbl">what</span>
              <button class="scope" data-s="all" aria-pressed="true">Everything</button>
              <button class="scope" data-s="position">Position only</button>
              <button class="scope" data-s="motion">Motion only</button>
            </div>
            <div class="row">
              <span class="lbl">to</span>
              <button id="copyc" title="Remember the primary clock">Copy</button>
              <button id="pastec" title="Paste into every selected clock">Paste into selection</button>
              <button id="all">All 24</button>
              <button id="row">Its row</button>
              <button id="col">Its column</button>
            </div>
            <p class="hint" id="clipnote"></p>

          <div class="sec">The pattern<span class="secnote">whole wall &mdash; not just the selection</span></div>
            <div class="row">
              <button id="play" class="icon" aria-pressed="true" title="Pause the motion"></button>
              <span class="hint inline" id="playnote">running</span>
            </div>

            <div class="row" id="entityRow">
              <button id="load" title="Read the pattern out of the entity">Load from wall</button>
              <button id="send" title="Write it back - the whole wall has it a second later">Send to wall</button>
              <button id="copy" title="The pattern as one line of text">Copy string</button>
            </div>
            <p class="hint" id="note"></p>
            <textarea id="out" spellcheck="false" style="display:none"></textarea>
          </div>
        </ha-card>`;

      this._cv = this.shadowRoot.querySelector("canvas");
      this._ctx = this._cv.getContext("2d");
      this._entityRow = this.shadowRoot.getElementById("entityRow");
      this._running = true;
      this._t = 0;

      const $ = id => this.shadowRoot.getElementById(id);
      this.$ = $;

      // ---- motion controls. Every edit goes through _rebase, or the hands
      // jump: an angle is pose + dir*speed*rate*t measured from t=0, so
      // changing a speed rewrites the whole history.
      this.shadowRoot.querySelectorAll("button.dir").forEach(b => {
        b.onclick = () => this._rebase(() => this._each(i => {
          P.get(i)[b.dataset.h === "0" ? "dirA" : "dirB"] = +b.dataset.v;
        }));
      });
      // Speed is either a rate or a RELATIONSHIP: "whatever my neighbour is
      // doing, plus a bit". That is what makes a gradient across the wall one
      // number instead of eight, and it is the thing the sandbox had and this
      // card did not - so a pattern drawn there could not be edited here
      // without silently flattening it to fixed rates.
      const key = h => (h === 0 ? "spdA" : "spdB");
      const writeSpeed = (h) => {
        const rel = this.$("mode" + h).value === "rel";
        const spec = rel
          ? { mode: "rel", from: this.$("from" + h).value,
              d: (+this.$("d" + h).value) / 100 }
          : { mode: "fixed", v: spdFromSlider(+this.$("spd" + h).value) };
        this._rebase(() => this._each(i => { P.get(i)[key(h)] = JSON.parse(JSON.stringify(spec)); }));
      };
      [0, 1].forEach(h => {
        $("spd" + h).oninput = () => writeSpeed(h);
        $("d" + h).oninput = () => writeSpeed(h);
        $("mode" + h).onchange = () => writeSpeed(h);
        $("from" + h).onchange = () => writeSpeed(h);
      });

      $("play").innerHTML = ICON_PAUSE;
      $("play").onclick = () => {
        this._running = !this._running;
        // U+23F8 pause, U+25B6 play. An icon, because the button's job is
        // obvious and the word was the widest thing in the row.
        $("play").innerHTML = this._running ? ICON_PAUSE : ICON_PLAY;
        $("play").title = this._running ? "Pause the motion" : "Run the motion";
        $("play").setAttribute("aria-pressed", String(this._running));
        $("playnote").textContent = this._running ? "running" : "paused";
        this._rebase(() => {});   // resume from where the hands are
      };
      // These two are inverses, and they are NOT symmetric in what they risk.
      //
      // `Back to pose` throws nothing away - it re-cuts every anchor from the
      // pose you configured, so the hands land on it and carry on from there.
      // Nothing is lost, so there is no reason to make you select first: it
      // takes ALL 24, and is the resync you reach for mid-run when the wall has
      // wandered off somewhere you did not mean.
      //
      // `Wall to pose` OVERWRITES the pose with whatever is on screen. That one
      // stays on the selection, because doing it to all 24 on a mis-click is
      // how you lose an afternoon's work.
      $("home").onclick = () => {
        for (let i = 0; i < C.NUM_CLOCKS; i++) {
          P.anchorAt(i, 0, P.get(i).h0, this._t);
          P.anchorAt(i, 1, P.get(i).h1, this._t);
        }
        this._sync();
        this._note(`Back to pose — all ${C.NUM_CLOCKS} clocks.`);
      };
      $("seed").onclick = () => {
        this._each(i => { P.setHomeAt(i, 0, this._angle(i, 0), this._t);
                          P.setHomeAt(i, 1, this._angle(i, 1), this._t); });
        this._sync();
        this._note(`Pose taken from where the hands are — ${this._sel.size} clock${
          this._sel.size > 1 ? "s" : ""}.`);
      };

      // ---- selection helpers. Shift-click works, but nothing on the canvas
      // says so, and "select the whole row" is the commonest thing you want.
      $("selall").onclick = () => this._select(() => true, "all 24");
      $("selrow").onclick = () => { const r = C.wallPos(this._primary).row;
        this._select(i => C.wallPos(i).row === r, "row " + r); };
      $("selcol").onclick = () => { const c = C.wallPos(this._primary).col;
        this._select(i => C.wallPos(i).col === c, "column " + c); };
      $("selnone").onclick = () => this._select(i => i === this._primary, "one clock");

      // ---- copy scope
      this.shadowRoot.querySelectorAll("button.scope").forEach(b => {
        b.onclick = () => {
          this._scope = b.dataset.s;
          this.shadowRoot.querySelectorAll("button.scope").forEach(o =>
            o.setAttribute("aria-pressed", String(o === b)));
          this._clipNote();
          this._note(`Copy will carry ${b.textContent.toLowerCase()}.`);
        };
      });
      $("copyc").onclick = () => {
        this._clip = P.copy(this._primary);
        this._clipFrom = this._primary;
        this._clipNote();
        this._note(`Copied clock ${this._primary}. Select targets, then Paste.`);
      };
      $("pastec").onclick = () => {
        if (!this._clip) { this._note("Nothing copied yet."); return; }
        this._spread(i => this._sel.has(i), this._clip);
      };
      $("all").onclick = () => this._spread(() => true);
      $("row").onclick = () => { const r = C.wallPos(this._primary).row;
                                 this._spread(i => C.wallPos(i).row === r); };
      $("col").onclick = () => { const c = C.wallPos(this._primary).col;
                                 this._spread(i => C.wallPos(i).col === c); };
      $("copy").onclick = () => {
        const t = P.toESPHome(this._cfg.name);
        $("out").style.display = "block"; $("out").value = t; $("out").select();
        try { navigator.clipboard.writeText(t); } catch (_) {}
        this._note(`${t.length} characters — paste into a Pattern text entity.`);
      };
      $("load").onclick = () => this._load();
      $("send").onclick = () => this._send();

      // ---- posing
      this._cv.addEventListener("pointerdown", e => this._down(e));
      this._cv.addEventListener("pointermove", e => { if (this._drag) this._move(e); });
      this._cv.addEventListener("pointerup", () => { this._drag = null; });
      this._cv.addEventListener("pointercancel", () => { this._drag = null; });
      // Hover says what a clock is SET to. 24 pairs of hands all turning at
      // slightly different rates is not something you can read off the canvas,
      // and the controls only ever show the primary.
      this._cv.addEventListener("pointermove", e => this._hover(e));
      this._cv.addEventListener("pointerleave", () => { this.$("tip").style.display = "none"; });

      this._clipNote();
      this._sync();
    }

    _each(fn) { this._sel.forEach(fn); }
    _note(t) { this.$("note").textContent = t; }

    // Remember where every hand is, apply the change, put them back. Without
    // this a speed edit teleports the wall.
    _rebase(mutate) {
      const seen = [];
      for (let i = 0; i < C.NUM_CLOCKS; i++) {
        seen.push(P.offsetAt(i, 0, this._t), P.offsetAt(i, 1, this._t));
      }
      const spec = [];
      for (let i = 0; i < C.NUM_CLOCKS; i++) {
        spec.push(C.wrap360(P.get(i).a0 + seen[i * 2]), C.wrap360(P.get(i).a1 + seen[i * 2 + 1]));
      }
      mutate();
      for (let i = 0; i < C.NUM_CLOCKS; i++) {
        P.anchorAt(i, 0, spec[i * 2], this._t);
        P.anchorAt(i, 1, spec[i * 2 + 1], this._t);
      }
      this._sync();
    }

    // What the clipboard is holding, said out loud. The scope buttons change
    // what a Paste carries, so it is folded into the same line rather than
    // being a second thing to cross-reference - and "nothing yet" is worth
    // saying too, next to a Paste button that would otherwise look pressable
    // with nothing behind it.
    _clipNote() {
      const el = this.$("clipnote");
      const what = this._scope === "all" ? "pose and motion"
                 : this._scope === "position" ? "position" : "motion";
      const held = this._clip != null;
      el.textContent = held
        ? `Holding clock ${this._clipFrom} — Paste carries ${what}.`
        : "Nothing copied yet — Copy remembers the primary clock.";
      el.classList.toggle("held", held);
      this.$("pastec").disabled = !held;
    }

    // Copy from `src` (or the primary) into everything `pred` matches.
    //
    // The SCOPE is the point: "make this whole row turn like this one but keep
    // where each hand is" is a normal thing to want, and pasting everything is
    // the one operation that cannot express it.
    _spread(pred, src) {
      const from = src || P.copy(this._primary);
      let n = 0;
      this._rebase(() => {
        for (let i = 0; i < C.NUM_CLOCKS; i++) {
          if (!pred(i) || i === this._clipFrom && src) continue;
          const cur = P.get(i);
          if (this._scope === "position") {
            cur.h0 = from.h0; cur.h1 = from.h1;
          } else if (this._scope === "motion") {
            cur.dirA = from.dirA; cur.dirB = from.dirB;
            cur.spdA = JSON.parse(JSON.stringify(from.spdA));
            cur.spdB = JSON.parse(JSON.stringify(from.spdB));
          } else {
            P.paste(i, from);
          }
          n++;
        }
      });
      // Position is a POSE change, so the hands have to go there - rebase
      // would otherwise hold them where they were and only move the anchor.
      if (this._scope !== "motion") {
        for (let i = 0; i < C.NUM_CLOCKS; i++) {
          if (!pred(i)) continue;
          P.anchorAt(i, 0, P.get(i).h0, this._t);
          P.anchorAt(i, 1, P.get(i).h1, this._t);
        }
      }
      this._sync();
      const what = this._scope === "all" ? "pose and motion"
                 : this._scope === "position" ? "position" : "motion";
      this._note(`Copied ${what} to ${n} clock${n === 1 ? "" : "s"}.`);
    }

    _select(pred, label) {
      this._sel = new Set();
      for (let i = 0; i < C.NUM_CLOCKS; i++) if (pred(i)) this._sel.add(i);
      if (!this._sel.has(this._primary)) this._primary = this._sel.values().next().value;
      this._sync();
      this._note(`Selected ${label} — edits apply to ${this._sel.size}.`);
    }

    // ---- entity ------------------------------------------------------------
    _syncEntity() {
      const on = !!(this._cfg.entity && this._hass && this._hass.states[this._cfg.entity]);
      ["load", "send"].forEach(id => { this.$(id).disabled = !on; });
      if (!this._cfg.entity) this._note("Set `entity:` to a Pattern text entity to load and send.");
    }
    _load() {
      const st = this._hass && this._hass.states[this._cfg.entity];
      if (!st) { this._note("Entity not found."); return; }
      const got = P.parseESPHome(st.state);
      if (!got) { this._note("That entity does not hold a pattern."); return; }
      got.clocks.forEach((c, i) => {
        const s = P.get(i);
        s.h0 = c.h0; s.h1 = c.h1; s.dirA = c.dir0; s.dirB = c.dir1;
        s.spdA = { mode: "fixed", v: c.v0 }; s.spdB = { mode: "fixed", v: c.v1 };
      });
      P.toHome(this._t);
      this._sync();
      this._note(`Loaded '${got.name}' from the wall.`);
    }
    _send() {
      const value = P.toESPHome(this._cfg.name);
      this._hass.callService("text", "set_value", { entity_id: this._cfg.entity, value });
      this._note(`Sent ${value.length} characters — the wall has it in about a second.`);
    }

    // ---- selection and posing ---------------------------------------------
    _layout() {
      const cv = this._cv, w = cv.width, h = cv.height;
      // NO digit gap. The wall is 24 separate 240x240 panels on one frame, so
      // its pitch is even by construction - the same distance right and down
      // between every pair of faces. A gap here drew a wall that does not
      // exist, and squeezed the cells besides: 8 + 0.35*3 columns of layout
      // inside a canvas whose aspect-ratio is 8/3.
      const gap = 0;
      const cell = Math.min(w / (C.WALL_COLS + gap * 3), h / C.WALL_ROWS);
      return { cell, gap: cell * gap, r: cell * 0.46,
               x0: (w - (cell * C.WALL_COLS + cell * gap * 3)) / 2 + cell / 2,
               y0: (h - cell * C.WALL_ROWS) / 2 + cell / 2 };
    }
    _at(e) {
      const b = this._cv.getBoundingClientRect();
      return { x: (e.clientX - b.left) * this._cv.width / b.width,
               y: (e.clientY - b.top) * this._cv.height / b.height };
    }
    _centre(i, L) {
      const p = C.wallPos(i);
      return { x: L.x0 + p.col * L.cell + Math.floor(p.col / 2) * L.gap, y: L.y0 + p.row * L.cell };
    }
    _pick(pt, L) {
      let best = -1, bd = L.cell * 0.6;
      for (let i = 0; i < C.NUM_CLOCKS; i++) {
        const c = this._centre(i, L);
        const d = Math.hypot(pt.x - c.x, pt.y - c.y);
        if (d < bd) { bd = d; best = i; }
      }
      return best;
    }
    _down(e) {
      const L = this._layout(), pt = this._at(e), i = this._pick(pt, L);
      if (i < 0) return;
      if (e.shiftKey) {                      // add to the selection, never drag
        if (this._sel.has(i) && this._sel.size > 1) this._sel.delete(i); else this._sel.add(i);
        this._primary = this._sel.has(i) ? i : this._sel.values().next().value;
        this._sync(); return;
      }
      const first = !(this._sel.size === 1 && this._sel.has(i));
      this._sel = new Set([i]); this._primary = i;
      this._sync();
      if (first) return;                     // first click selects only
      const c = this._centre(i, L);
      const a = C.wrap360(Math.atan2(pt.y - c.y, pt.x - c.x) * 180 / Math.PI + 90);
      const d0 = Math.abs(C.shortestDelta(this._angle(i, 0), a));
      const d1 = Math.abs(C.shortestDelta(this._angle(i, 1), a));
      this._drag = { hand: d0 <= d1 ? 0 : 1 };
      this._cv.setPointerCapture(e.pointerId);
      this._move(e);
    }
    _move(e) {
      const L = this._layout(), pt = this._at(e), c = this._centre(this._primary, L);
      const snap = this._cfg.snap || 15;
      let a = C.wrap360(Math.atan2(pt.y - c.y, pt.x - c.x) * 180 / Math.PI + 90);
      a = ((Math.round(a / snap) * snap) % 360 + 360) % 360;
      this._each(i => P.setHomeAt(i, this._drag.hand, a, this._t));
      this._sync();
    }
    _hover(e) {
      const tip = this.$("tip");
      if (this._drag) { tip.style.display = "none"; return; }
      const L = this._layout(), pt = this._at(e), i = this._pick(pt, L);
      if (i < 0) { tip.style.display = "none"; return; }
      const s = P.get(i), r = P.resolved()[i], { col, row } = C.wallPos(i);
      const arrow = d => (d < 0 ? "\u21ba ccw" : d > 0 ? "\u21bb cw" : "\u25cf still");
      const line = (label, ang, dir, v, sp) =>
        `${label}  ${String(Math.round(ang)).padStart(3)}\u00b0  ${arrow(dir).padEnd(9)}` +
        (dir ? `${(v * MAX_RATE).toFixed(1)}\u00b0/s` : "") +
        (sp.mode === "rel"
          ? `  (${sp.from}${sp.d >= 0 ? "+" : ""}${(sp.d * 100).toFixed(1)}%)` : "");
      tip.textContent =
        `clock ${i} \u00b7 col ${col} row ${row}${this._sel.has(i) ? "  (selected)" : ""}\n` +
        line("A", s.h0, s.dirA, r[0], s.spdA) + "\n" +
        line("B", s.h1, s.dirB, r[1], s.spdB);
      // Positioned over the clock, in CSS pixels - the canvas backing store is
      // scaled for retina, so its own coordinates are the wrong unit here.
      const box = this._cv.getBoundingClientRect();
      const c = this._centre(i, L), k = box.width / this._cv.width;
      tip.style.left = (c.x * k) + "px";
      tip.style.top = (c.y * k - L.r * k) + "px";
      tip.style.display = "block";
    }

    _angle(i, hand) {
      const s = P.get(i);
      return C.wrap360((hand ? s.a1 : s.a0) + P.offsetAt(i, hand, this._t));
    }

    // ---- controls reflect the primary --------------------------------------
    _sync() {
      const s = P.get(this._primary), r = P.resolved()[this._primary];
      const { col, row } = C.wallPos(this._primary);
      const extra = this._sel.size > 1 ? ` +${this._sel.size - 1} more — edits apply to all ${this._sel.size}` : "";
      this.$("who").textContent =
        `clock ${this._primary} · col ${col} row ${row}${extra}` +
        ` — ${(r[0] * MAX_RATE).toFixed(1)}°/s · ${(r[1] * MAX_RATE).toFixed(1)}°/s`;
      this.shadowRoot.querySelectorAll("button.dir").forEach(b => {
        const cur = b.dataset.h === "0" ? s.dirA : s.dirB;
        b.setAttribute("aria-pressed", String(+b.dataset.v === cur));
      });
      [0, 1].forEach(h => {
        const v = r[h];                          // the RESOLVED rate
        const sp = h === 0 ? s.spdA : s.spdB;
        const rel = sp.mode === "rel";
        this.$("mode" + h).value = rel ? "rel" : "fixed";
        this.$("rel" + h).style.display = rel ? "flex" : "none";
        // The slider shows the resolved rate either way, so a relative hand
        // still tells you what it is actually doing - it is just not what you
        // drag to change it.
        this.$("spd" + h).value = sliderFromSpd(v);
        this.$("spd" + h).disabled = rel;
        if (rel) {
          this.$("from" + h).value = sp.from;
          this.$("d" + h).value = Math.round(sp.d * 100 * 2) / 2;
          this.$("d" + h + "v").textContent =
            `${sp.d >= 0 ? "+" : ""}${(sp.d * 100).toFixed(1)}%`;
        }
        this.$("spd" + h + "v").textContent =
          `${sliderFromSpd(v).toFixed(1)}% · ${(v * MAX_RATE).toFixed(1)}°/s`;
      });
      this._syncEntity();
    }

    // ---- loop --------------------------------------------------------------
    _start() {
      if (this._raf) return;
      let last = performance.now();
      const tick = (t) => {
        this._raf = requestAnimationFrame(tick);
        const dt = Math.min((t - last) / 1000, 0.1);
        last = t;
        if (this._running) this._t += dt;
        this._render();
      };
      this._raf = requestAnimationFrame(tick);
    }
    _stop() { if (this._raf) cancelAnimationFrame(this._raf); this._raf = null; }

    _render() {
      const cv = this._cv, ctx = this._ctx;
      const rect = cv.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      const w = Math.max(1, Math.round(rect.width * dpr)), h = Math.max(1, Math.round(rect.height * dpr));
      if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
      ctx.fillStyle = "#000"; ctx.fillRect(0, 0, w, h);

      const L = this._layout(), lw = Math.max(1, L.r / 8);
      for (let i = 0; i < C.NUM_CLOCKS; i++) {
        const c = this._centre(i, L);
        if (this._sel.has(i)) {
          ctx.strokeStyle = i === this._primary ? "#6ea8fe" : "#31537f";
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(c.x, c.y, L.r + 5, 0, Math.PI * 2); ctx.stroke();
        }
        ctx.strokeStyle = "#fff"; ctx.fillStyle = "#fff";
        ctx.lineWidth = lw; ctx.lineCap = "butt";
        for (const hand of [0, 1]) {
          const rad = (this._angle(i, hand) - 90) * Math.PI / 180;
          ctx.beginPath(); ctx.moveTo(c.x, c.y);
          ctx.lineTo(c.x + Math.cos(rad) * L.r, c.y + Math.sin(rad) * L.r);
          ctx.stroke();
        }
        ctx.beginPath(); ctx.arc(c.x, c.y, lw / 2, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  customElements.define("clockclock24-editor-card", ClockClock24EditorCard);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: "clockclock24-editor-card",
    name: "ClockClock 24 — pattern editor",
    description: "Draw a motion pattern, watch it run, and send it to the wall.",
    preview: false,
  });
})();

